/*!****************************************************************************
 * @file  combus_defs.h
 * @brief The ComBus: the shared register of a node, and its channels.
 *
 * @details Every module of a board reads and writes the ComBus instead of calling the
 *   others: the inputs (sticks, buttons, links) write it, the logic reads and writes
 *   it, the outputs (motors, lights, links) read it.
 *
 *   It holds two arrays of channels, generated by the ComBus Builder from the .cb
 *   files (combus.h, combus.cpp):
 *   - analog channels, a uint16_t each;
 *   - digital channels, a bool each.
 *
 *   Each channel carries, besides its value:
 *   - its layer (ChanLayer): who may write it;
 *   - its flow (ChanFlow): which way it travels, on each kind of link;
 *   - for an analog channel, the place of its logical zero (zeroAtNeutral);
 *   - for a digital channel, its both_or merge (BothOrMerge).
 *
 *   The writes go through combus_access.h, which checks the layer.
 *
 * @note Do not change the uint16_t size of an analog value: the frames, the
 *   neutral value and the sub-values of some channels depend on it.
 *******************************************************************************///
#pragma once

#include <stdint.h>

#include <defs/machines_defs.h>



// =============================================================================
// 1. CHANNEL IDS
// =============================================================================

/**
 * @brief The channel IDs, declared only.
 *
 * @details A fixed underlying type makes them complete types: enough for fields and
 *   parameters.  The enumerators come from the generated <combus_ids.h>, the arrays
 *   from <combus.h>.
 *
 *   Global scope: a translation unit sees one machine configuration.  A multi-machine
 *   remote that needs several in the same unit would bring back a namespace.
 */

enum class AnalogComBusID  : uint8_t;
enum class DigitalComBusID : uint8_t;



// =============================================================================
// 2. LAYER AND DIRECTION
// =============================================================================

/**
 * @brief Layer of a channel: who may write it.
 *
 * @details Every write gives the layer of its writer; combus_access.h compares it
 *   with the layer of the channel:
 *   - BASE: any writer, this board, the other boards of the node, or another node;
 *   - SYSTEM: the boards of this node (writer SYSTEM or BOARD);
 *   - BOARD: this board only (writer BOARD);
 *   - UNDEFINED: nobody, a channel without a layer is never written.
 *
 *   A received frame writes with the layer of its link: BASE from another node,
 *   SYSTEM from another board.  A BOARD channel never travels.
 *
 *   The layers are nested on the wire: the channels sent to another board (SYSTEM
 *   view) start with those sent to another node (BASE view).
 */

enum class ChanLayer : uint8_t {
	UNDEFINED = 0x00,   ///< no layer assigned: no write accepted
	BOARD     = 0x01,   ///< this board only
	SYSTEM    = 0x02,   ///< the boards of this node
	BASE      = 0x03    ///< every node
};


/**
 * @brief Direction of a channel on a link, as a bitmask.
 *
 * @details bit 0 = Uplink (this board sends it), bit 1 = Downlink (this board
 *   receives it); Both = Uplink | Downlink.  A received frame writes a channel only
 *   when its direction on that link includes Downlink.
 *
 *   It is a data field, apart from the layer: the layer says who may write, the
 *   direction what travels.
 */

enum class Direction : uint8_t {
	None     = 0,
	Uplink   = 1,
	Downlink = 2,
	Both     = 3
};



// =============================================================================
// 3. CHANNELS
// =============================================================================

/**
 * @brief Which way a channel travels, on each kind of link.
 *
 * @details A channel crosses two kinds of links, and its direction is not the same on
 *   both:
 *   - betweenNodes: on a link to another node (remote, trailer).  This is the
 *     direction written in the .cb;
 *   - betweenBoards: on a link between the boards of this node, computed by the
 *     builder for this board.  A BASE command enters the node through the board linked
 *     to the other node, which passes it on (Uplink); the other boards receive it
 *     (Downlink).  For a SYSTEM channel: the direction declared for the node.
 *
 *   A channel that this board produces is therefore never overwritten by a frame.
 */

struct ChanFlow {
	Direction betweenNodes  = Direction::None;   ///< on a link to another node (the .cb direction)
	Direction betweenBoards = Direction::None;   ///< on a link between boards (computed for this board)
};


/**
 * @brief OR merge of a both_or channel (anti ping-pong, see protocol/both_or.md).
 *
 * @details The value read by everyone is this board's own value OR the values
 *   received from the live links.  A received frame never overwrites it:
 *   com_rx_update() refreshes `remote` each cycle and every local write recomputes the
 *   value.
 */

struct BothOrMerge {
	bool enabled = false;   ///< the channel is declared both_or
	bool local   = false;   ///< last value written by this board's own code
	bool written = false;   ///< this board wrote it at least once (otherwise it does not contribute)
	bool remote  = false;   ///< OR of the values received from the live links
};

	// The sub-structures have no padding inside.
static_assert(sizeof(ChanFlow)    == 2u * sizeof(Direction), "ChanFlow must hold two Direction, no padding");
static_assert(sizeof(BothOrMerge) == 4u * sizeof(bool),      "BothOrMerge must hold four bool, no padding");


/**
 * @brief An analog channel.
 *
 * @details `zeroAtNeutral` places the logical zero in the raw range: at CbusNeutral
 *   (`.cb` `zeroAt: neutral`), else at 0.  It is not a type choice: `value` stays a
 *   raw uint16_t and the frame is unchanged; only the application accessors of
 *   combus_access.h apply the offset.
 *
 *   The order of the fields is the one of the generated initializers.
 */

struct AnalogComBus {
	const char* infoName;                           ///< short description, for debugging and dashboards
	uint16_t    value;                              ///< raw value (0-65535)
	ChanLayer   layer         = ChanLayer::BOARD;   ///< who may write it
	ChanFlow    flow          = {};                 ///< which way it travels, on each kind of link
	bool        zeroAtNeutral = false;              ///< logical zero at CbusNeutral, else at 0
};

	// zeroAtNeutral sits in padding that already existed: an analog channel still
	// takes 12 bytes on the ESP32 (32-bit pointer).
#if UINTPTR_MAX == 0xFFFFFFFFu
static_assert(sizeof(AnalogComBus) == 12u, "AnalogComBus must stay 12 bytes on a 32-bit target");
#endif


/**
 * @brief A digital channel.
 *
 * @details The order of the fields is the one of the generated initializers.
 */

struct DigitalComBus {
	const char* infoName;                     ///< short description, for debugging and dashboards
	bool        value;                        ///< current state
	ChanLayer   layer  = ChanLayer::BOARD;    ///< who may write it
	ChanFlow    flow   = {};                  ///< which way it travels, on each kind of link
	BothOrMerge bothOr = {};                  ///< OR merge, used when bothOr.enabled
};



// =============================================================================
// 4. COMBUS
// =============================================================================

/**
 * @brief The ComBus of a node: its channel arrays, and the time of the last frame.
 *
 * @details The run level is a channel like any other (RUNLEVEL, SYSTEM analog), and
 *   the health of the links is written by contributor channels: neither has a field
 *   here.
 */

struct ComBus {
		// Transport
	uint32_t       lastFrameMs = 0;   ///< millis() at the last frame applied (combus_frame_apply)

		// Channel arrays
	AnalogComBus*  analogBus;         ///< analog channels, indexed by AnalogComBusID
	DigitalComBus* digitalBus;        ///< digital channels, indexed by DigitalComBusID
	uint32_t       analogBusMaxVal;   ///< largest analog value (65535)
};

// EOF combus_defs.h
